import{_ as o,a0 as n,w as r,s as p,I as s,x as e,a1 as a,A as d,ao as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"systemd 日志维护指南（附实例） | LCTT x X-CMD","titleTemplate":false,"description":"systemd 日志维护指南（附实例） | LCTT (202302) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"systemd 日志维护指南（附实例） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"systemd 日志维护指南（附实例） | LCTT (202302) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202302/20221109.3 ⭐️⭐️ A Guide to systemd journal Maintenance [With Examples]","title":"systemd 日志维护指南（附实例）","tag":"202302","desc":""},"relativePath":"202302/20221109.3 ⭐️⭐️ A Guide to systemd journal Maintenance [With Examples].md","filePath":"[post].md"}'),u={name:"202302/20221109.3 ⭐️⭐️ A Guide to systemd journal Maintenance [With Examples].md"};function g(h,t,m,c,f,y){const l=n("Link");return r(),p("div",null,[t[32]||(t[32]=s("h1",{id:"systemd-日志维护指南-附实例",tabindex:"-1"},[e("systemd 日志维护指南（附实例） "),s("a",{class:"header-anchor",href:"#systemd-日志维护指南-附实例","aria-label":"Permalink to “systemd 日志维护指南（附实例）”"},"​")],-1)),t[33]||(t[33]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/202302/10/072955z20ipg8vlpvdt1jq.jpg",alt:""})],-1)),t[34]||(t[34]=s("blockquote",null,[s("p",null,"systemd 内置了很多管理系统日志的功能。在本指南中，我们将介绍如何管理系统日志，并对其采取轮换、归档和清除日志等操作。我们还解释了手动系统日志清理方法和使用配置文件的变化。")],-1)),s("p",null,[t[1]||(t[1]=e("如果你的 Linux 发行版支持 ",-1)),a(l,{href:"https://www.freedesktop.org/wiki/Software/systemd/"},{default:d(()=>[...t[0]||(t[0]=[e("systemd",-1)])]),_:1}),t[2]||(t[2]=e("，那么从启动时开始，它每秒钟都会从系统的所有进程和应用程序中收集日志。所有这些日志事件都由 systemd 的 ",-1)),t[3]||(t[3]=s("code",null,"journald",-1)),t[4]||(t[4]=e(" 守护程序管理。journald 收集所有的日志（信息、警告、错误等），并将其作为二进制数据存储在磁盘文件中。",-1))]),t[35]||(t[35]=s("p",null,"由于日志保留在磁盘中，而且每秒钟都在收集，所以它占用了巨大的磁盘空间；特别是对于旧的系统、服务器来说。例如，在我的一个运行了一年左右的测试系统中，日志文件的大小是 GB 级的。",-1)),t[36]||(t[36]=s("p",null,"如果你管理多个系统、服务器，建议一定要正确管理 journald 日志，以便高效运行。让我们来看看如何管理日志文件。",-1)),t[37]||(t[37]=s("h3",{id:"systemd-日志维护",tabindex:"-1"},[e("systemd 日志维护 "),s("a",{class:"header-anchor",href:"#systemd-日志维护","aria-label":"Permalink to “systemd 日志维护”"},"​")],-1)),s("p",null,[t[6]||(t[6]=e("使用 systemd 的 ",-1)),t[7]||(t[7]=s("code",null,"journalctl",-1)),t[8]||(t[8]=e(" 工具，你可以查询这些日志，对其进行各种操作。例如，查看不同启动时的日志文件，检查特定进程或应用程序的最后警告和错误。如果你对这些不了解，我建议你在学习本指南之前先快速浏览一下此教程：",-1)),a(l,{href:"https://www.debugpoint.com/2020/12/systemd-journalctl/"},{default:d(()=>[...t[5]||(t[5]=[e("使用 journalctl 查看和分析 systemd 日志（附实例）",-1)])]),_:1}),t[9]||(t[9]=e(" 》。",-1))]),t[38]||(t[38]=i('<h4 id="物理日记的日志文件在哪里" tabindex="-1">物理日记的日志文件在哪里？ <a class="header-anchor" href="#物理日记的日志文件在哪里" aria-label="Permalink to “物理日记的日志文件在哪里？”">​</a></h4><p>systemd 的 journald 守护进程在每次启动时都会收集日志。这意味着，它根据启动情况对日志文件进行分类。</p><p>日志以二进制形式存储在路径 <code>/var/log/journal</code>，文件夹为机器 ID。</p><p>比如说：</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/01/Screenshot-of-physical-journal-file-1.jpg" alt="日志文件位置的截图-1"></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/01/Screenshot-of-physical-journal-files-2.jpg" alt="日志文件位置的截图-2"></p><p>另外，请记住，根据系统配置，运行时日志文件被存储在 <code>/run/log/journal/</code>。而这些在每次启动时都会被删除。</p><h4 id="我可以手动删除日志文件吗" tabindex="-1">我可以手动删除日志文件吗？ <a class="header-anchor" href="#我可以手动删除日志文件吗" aria-label="Permalink to “我可以手动删除日志文件吗？”">​</a></h4><p>你可以，但不要这样做。相反，请按照下面的说明，使用 <code>journalctl</code> 工具清除日志文件以释放磁盘空间。</p><h4 id="systemd-的日志文件占用了多少磁盘空间" tabindex="-1">systemd 的日志文件占用了多少磁盘空间？ <a class="header-anchor" href="#systemd-的日志文件占用了多少磁盘空间" aria-label="Permalink to “systemd 的日志文件占用了多少磁盘空间？”">​</a></h4><p>打开一个终端，运行以下命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>journalctl --disk-usage</span></span></code></pre></div><p>这应该为你提供系统中的日志文件实际使用的数量。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/01/journalctl-disk-usage-command.jpg" alt="journalctl 磁盘使用命令"></p><p>如果你有一个图形化的桌面环境，你可以打开文件管理器，浏览路径 <code>/var/log/journal</code>，并检查属性。</p><h4 id="systemd-日志清理过程" tabindex="-1">systemd 日志清理过程 <a class="header-anchor" href="#systemd-日志清理过程" aria-label="Permalink to “systemd 日志清理过程”">​</a></h4><p>清理日志文件的有效方法应该是通过 <code>journald.conf</code> 配置文件来完成。正常情况下，即使 <code>journalctl</code> 提供了删除日志文件的工具，你也不应该手动删除这些文件。</p>',17)),s("p",null,[t[11]||(t[11]=e("让我们来看看如何 ",-1)),a(l,{href:"https://www.debugpoint.com#delete-using-journal-conf"},{default:d(()=>[...t[10]||(t[10]=[e("手动",-1)])]),_:1}),t[12]||(t[12]=e(" 删除它，然后我将解释 ",-1)),t[13]||(t[13]=s("code",null,"journald.conf",-1)),t[14]||(t[14]=e(" 中的配置变化，这样你就不需要时不时地手动删除文件；相反，systemd 会根据你的配置自动处理它。",-1))]),t[39]||(t[39]=i('<h5 id="手动删除" tabindex="-1">手动删除 <a class="header-anchor" href="#手动删除" aria-label="Permalink to “手动删除”">​</a></h5><p>首先，你必须 <code>flush</code> 和 <code>rotate</code> 日志文件。<ruby>轮换<rt>rotate</rt></ruby>是将当前活动的日志文件归档，并立即开始创建一个新的日志文件继续记录日志。<ruby>冲洗<rt>flush</rt></ruby> 开关要求日志守护进程将存储在 <code>/run/log/journal/</code> 中的所有日志数据冲入 <code>/var/log/journal/</code>，如果持久性存储被启用的话。</p><p>然后，在 <code>flush</code> 和 <code>rotate</code> 之后，你需要用 <code>vacuum-size</code>、<code>vacuum-time</code> 和 <code>vacuum-files</code> 选项运行 <code>journalctl</code> 来强制 systemd 清除日志。</p><p>例 1：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo journalctl --flush --rotate</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo journalctl --vacuum-time=1s</span></span></code></pre></div><p>上面这组命令会删除所有存档的日志文件，直到最后一秒。这有效地清除了一切。因此，在运行该命令时要小心。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/01/journal-clean-up-example.jpg" alt="日志清理-例子"></p><p>清理完毕后：</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/01/After-clean-up-journal-space-usage.jpg" alt="清理后--日志的占用空间"></p><p>你也可以根据你的需要在 <code>--vacuum-time</code> 的数字后面提供以下后缀：</p><ul><li><code>s</code>：秒</li><li><code>m</code>：分钟</li><li><code>h</code>：小时</li><li><code>days</code>：天</li><li><code>months</code>：月</li><li><code>weeks</code>：周</li><li><code>years</code>：年</li></ul><p>例 2：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo journalctl --flush --rotate</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo journalctl --vacuum-size=400M</span></span></code></pre></div><p>这将清除所有存档的日志文件，并保留最后 400MB 的文件。记住这个开关只适用于存档的日志文件，不适用于活动的日志文件。你也可以使用后缀，如下所示。</p><ul><li><code>K</code>：KB</li><li><code>M</code>：MB</li><li><code>G</code>：GB</li></ul><p>例 3：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo journalctl --flush --rotate</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo journalctl --vacuum-files=2</span></span></code></pre></div><p><code>vacuum-files</code> 选项会清除所有低于指定数量的日志文件。因此，在上面的例子中，只有最后两个日志文件被保留，其他的都被删除。同样，这只对存档的文件有效。</p><p>如果你愿意，你可以把两种选项结合起来，但我建议不要这样做。然而，如果同时使用两个选项，请确保先用 <code>--rotate</code> 选项运行。</p><h3 id="使用配置文件自动删除" tabindex="-1">使用配置文件自动删除 <a class="header-anchor" href="#使用配置文件自动删除" aria-label="Permalink to “使用配置文件自动删除”">​</a></h3><p>虽然上述方法很好，也很容易使用，但建议你使用 journald 配置文件来控制日志文件的清理过程，该文件存在于 <code>/etc/systemd/journald.conf</code>。</p><p>systemd 为你提供了许多参数来有效管理日志文件。通过组合这些参数，你可以有效地限制日志文件所占用的磁盘空间。让我们来看看。</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;">journald.conf 参数</th><th style="text-align:left;">描述</th><th style="text-align:left;">实例</th></tr></thead><tbody><tr><td style="text-align:left;"><code>SystemMaxUse</code></td><td style="text-align:left;">指定日志在持久性存储中可使用的最大磁盘空间</td><td style="text-align:left;"><code>SystemMaxUse=500M</code></td></tr><tr><td style="text-align:left;"><code>SystemKeepFree</code></td><td style="text-align:left;">指定在将日志条目添加到持久性存储时，日志应留出的空间量。</td><td style="text-align:left;"><code>SystemKeepFree=100M</code></td></tr><tr><td style="text-align:left;"><code>SystemMaxFileSize</code></td><td style="text-align:left;">控制单个日志文件在被轮换之前在持久性存储中可以增长到多大。</td><td style="text-align:left;"><code>SystemMaxFileSize=100M</code></td></tr><tr><td style="text-align:left;"><code>RuntimeMaxUse</code></td><td style="text-align:left;">指定在易失性存储中可以使用的最大磁盘空间（在 <code>/run</code> 文件系统内）。</td><td style="text-align:left;"><code>RuntimeMaxUse=100M</code></td></tr><tr><td style="text-align:left;"><code>RuntimeKeepFree</code></td><td style="text-align:left;">指定将数据写入易失性存储（在 <code>/run</code> 文件系统内）时为其他用途预留的空间数量。</td><td style="text-align:left;"><code>RuntimeMaxUse=100M</code></td></tr><tr><td style="text-align:left;"><code>RuntimeMaxFileSize</code></td><td style="text-align:left;">指定单个日志文件在被轮换之前在易失性存储（在 <code>/run</code> 文件系统内）所能占用的空间量。</td><td style="text-align:left;"><code>RuntimeMaxFileSize=200M</code></td></tr></tbody></table></div><p>如果你在运行中的系统的 <code>/etc/systemd/journald.conf</code> 文件中添加这些值，那么在更新文件后，你必须重新启动 journald。要重新启动，请使用以下命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl restart systemd-journald</span></span></code></pre></div><h3 id="核实日志文件" tabindex="-1">核实日志文件 <a class="header-anchor" href="#核实日志文件" aria-label="Permalink to “核实日志文件”">​</a></h3><p>在你清理完文件后，检查日志文件的完整性是比较明智的。要做到这一点，请运行下面的命令。该命令显示了日志文件是否通过（<code>PASS</code>）、失败（<code>FAIL</code>）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>journalctl --verify</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/01/verify-log-files.png" alt="验证日志文件"></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>希望本指南能帮助你了解 systemd 日志管理流程的基本情况。通过这些，你可以通过限制空间、清除旧的日志文件来管理系统或服务器中的日志文件所使用的磁盘空间。这些只是指导性的命令，你可以通过多种方式组合这些命令来实现你的系统需求。</p>',34)),s("ul",null,[s("li",null,[a(l,{href:"https://www.freedesktop.org/software/systemd/man/journalctl.html"},{default:d(()=>[...t[15]||(t[15]=[e("journalctl 手册",-1)])]),_:1})]),s("li",null,[a(l,{href:"https://www.freedesktop.org/software/systemd/man/journald.conf.html"},{default:d(()=>[...t[16]||(t[16]=[e("journald.conf 手册",-1)])]),_:1})])]),t[40]||(t[40]=s("hr",null,null,-1)),s("p",null,[t[18]||(t[18]=e("via: ",-1)),a(l,{href:"https://www.debugpoint.com/systemd-journald-clean/"},{default:d(()=>[...t[17]||(t[17]=[e("https://www.debugpoint.com/systemd-journald-clean/",-1)])]),_:1})]),s("p",null,[t[23]||(t[23]=e("作者：",-1)),a(l,{href:"https://www.debugpoint.com/author/admin1/"},{default:d(()=>[...t[19]||(t[19]=[e("Arindam",-1)])]),_:1}),t[24]||(t[24]=e(" 选题：",-1)),a(l,{href:"https://github.com/lkxed"},{default:d(()=>[...t[20]||(t[20]=[e("lkxed",-1)])]),_:1}),t[25]||(t[25]=e(" 译者：",-1)),a(l,{href:"https://github.com/Chao-zhi"},{default:d(()=>[...t[21]||(t[21]=[e("Chao-zhi",-1)])]),_:1}),t[26]||(t[26]=e(" 校对：",-1)),a(l,{href:"https://github.com/wxy"},{default:d(()=>[...t[22]||(t[22]=[e("wxy",-1)])]),_:1})]),s("p",null,[t[29]||(t[29]=e("本文由 ",-1)),a(l,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...t[27]||(t[27]=[e("LCTT",-1)])]),_:1}),t[30]||(t[30]=e(" 原创编译，",-1)),a(l,{href:"https://linux.cn/"},{default:d(()=>[...t[28]||(t[28]=[e("Linux中国",-1)])]),_:1}),t[31]||(t[31]=e(" 荣誉推出",-1))])])}const w=o(u,[["render",g]]);export{x as __pageData,w as default};
